        search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){String q=s.toString().trim().toLowerCase(Locale.ROOT);if(q.isEmpty()){results.setVisibility(View.GONE);scroll.setVisibility(View.VISIBLE);return;}scroll.setVisibility(View.GONE);if(results.getParent()==null)page.addView(results,new LinearLayout.LayoutParams(-1,0,1));results.setVisibility(View.VISIBLE);List<String> labels=new ArrayList<>(),kinds=new ArrayList<>();List<SettingsSchema.Option> options=new ArrayList<>();for(String k:SettingsState.KINDS)for(SettingsSchema.Option o:schema.options(k))if(matches(o,q)){labels.add(getString(R.string.phase2_settings_search_result,o.label==null?o.key:o.label,label(k),o.page,o.key));kinds.add(k);options.add(o);}results.setAdapter(new SearchAdapter(labels));results.setOnItemClickListener((parent,v,pos,id)->{SettingsSchema.Option o=options.get(pos);highlight=o.key;tab=o.page;advanced=true;open(kinds.get(pos),"","");});}public void afterTextChanged(Editable e){}});
